import { Injectable } from '@angular/core';
import { Product } from './product.model';

@Injectable({ providedIn: 'root' })
export class ProductCatalogService {
  readonly products: readonly Product[] = [
    { id: 'alexa', name: 'Alexa', category: 'Asistentes', image: 'assets/images/Alexa.png', description: 'Un asistente para acompañarte en tu día a día.', features: ['Consultá modelo y compatibilidad', 'Consultá las opciones disponibles'], price: null },
    { id: 'foco-smart', name: 'Foco smart', category: 'Iluminación', image: 'assets/images/foco.png', description: 'Dale un nuevo ritmo a la iluminación de tus espacios.', features: ['Consultá potencia y tipo de rosca', 'Consultá compatibilidad'], price: null },
    { id: 'control-smart', name: 'Control smart', category: 'Control', image: 'assets/images/control.png', description: 'Descubrí opciones para conectar tus equipos.', features: ['Consultá equipos compatibles', 'Consultá conexión y configuración'], price: null },
    { id: 'camara-interna', name: 'Cámara interna', category: 'Seguridad', image: 'assets/images/camaraInterna.png', description: 'Encontrá una opción de monitoreo para tus interiores.', features: ['Consultá resolución y almacenamiento', 'Consultá las opciones de instalación'], price: null },
    { id: 'camara-externa', name: 'Cámara externa', category: 'Seguridad', image: 'assets/images/camaraExterna.png', description: 'Explorá soluciones de monitoreo para tus accesos.', features: ['Consultá protección para exteriores', 'Consultá resolución y almacenamiento'], price: null },
    { id: 'sensor', name: 'Sensor smart', category: 'Seguridad', image: 'assets/images/sensor.png', description: 'Sumá sensores a tu proyecto de automatización.', features: ['Consultá tipo de sensor', 'Consultá compatibilidad y alimentación'], price: null },
    { id: 'interruptor', name: 'Interruptor smart', category: 'Iluminación', image: 'assets/images/interruptor.png', description: 'Descubrí opciones de control para tus luces.', features: ['Consultá cantidad de teclas', 'Consultá requisitos de instalación'], price: null },
  ];
}
